CREATE TYPE "Role" AS ENUM ('STUDENT','SUPERVISOR','COORDINATOR');
CREATE TYPE "PlacementStatus" AS ENUM ('PENDING','APPROVED','REJECTED');
CREATE TYPE "AttendanceStatus" AS ENUM ('PRESENT','LATE','ABSENT');
CREATE TYPE "DocumentStatus" AS ENUM ('DRAFT','SUBMITTED','RETURNED','APPROVED','SIGNED','COORDINATOR_REVIEWED');
CREATE TABLE "user_profiles"("id" TEXT PRIMARY KEY,"auth_user_id" TEXT NOT NULL UNIQUE,"email" TEXT NOT NULL UNIQUE,"name" TEXT NOT NULL,"role" "Role" NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "students"("id" TEXT PRIMARY KEY,"user_id" TEXT NOT NULL UNIQUE REFERENCES "user_profiles"("id"),"student_number" TEXT NOT NULL UNIQUE,"program" TEXT NOT NULL);
CREATE TABLE "companies"("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"address" TEXT,"approved" BOOLEAN NOT NULL DEFAULT false,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "supervisor_assignments"("id" TEXT PRIMARY KEY,"user_id" TEXT NOT NULL UNIQUE REFERENCES "user_profiles"("id"),"company_id" TEXT NOT NULL REFERENCES "companies"("id"),"can_sign" BOOLEAN NOT NULL DEFAULT true,"public_key_pem" TEXT,"key_id" TEXT,"active" BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE "ojt_placements"("id" TEXT PRIMARY KEY,"student_id" TEXT NOT NULL UNIQUE REFERENCES "students"("id"),"company_id" TEXT NOT NULL REFERENCES "companies"("id"),"supervisor_id" TEXT,"status" "PlacementStatus" NOT NULL DEFAULT 'PENDING',"submitted_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"decided_at" TIMESTAMP(3));
CREATE TABLE "biometric_enrollments"("id" TEXT PRIMARY KEY,"student_id" TEXT NOT NULL UNIQUE REFERENCES "students"("id"),"provider_reference" TEXT NOT NULL,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "attendance_records"("id" TEXT PRIMARY KEY,"student_id" TEXT NOT NULL REFERENCES "students"("id"),"date" DATE NOT NULL,"status" "AttendanceStatus" NOT NULL,"time_in" TIMESTAMP(3),"time_out" TIMESTAMP(3),"device_id" TEXT NOT NULL,"method" TEXT NOT NULL,"verification" BOOLEAN NOT NULL DEFAULT false,UNIQUE("student_id","date"));
CREATE TABLE "daily_documentations"("id" TEXT PRIMARY KEY,"student_id" TEXT NOT NULL REFERENCES "students"("id"),"day" INTEGER NOT NULL,"status" "DocumentStatus" NOT NULL DEFAULT 'DRAFT',"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,UNIQUE("student_id","day"));
CREATE TABLE "document_versions"("id" TEXT PRIMARY KEY,"documentation_id" TEXT NOT NULL REFERENCES "daily_documentations"("id"),"version" INTEGER NOT NULL,"activities" TEXT NOT NULL,"skills" TEXT NOT NULL,"challenges" TEXT NOT NULL,"attachments" JSONB,"submitted_at" TIMESTAMP(3),"immutable" BOOLEAN NOT NULL DEFAULT false,UNIQUE("documentation_id","version"));
CREATE TABLE "approval_records"("id" TEXT PRIMARY KEY,"version_id" TEXT NOT NULL REFERENCES "document_versions"("id"),"supervisor_id" TEXT NOT NULL,"decision" TEXT NOT NULL,"remarks" TEXT,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "digital_signatures"("id" TEXT PRIMARY KEY,"version_id" TEXT NOT NULL UNIQUE REFERENCES "document_versions"("id"),"signer_id" TEXT NOT NULL,"digest" TEXT NOT NULL,"signature" TEXT NOT NULL,"key_id" TEXT NOT NULL,"signed_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "audit_logs"("id" TEXT PRIMARY KEY,"actor_id" TEXT,"action" TEXT NOT NULL,"target_type" TEXT NOT NULL,"target_id" TEXT NOT NULL,"details" JSONB,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
-- Newly authenticated accounts start as students; elevated roles are assigned by trusted administrators.
CREATE OR REPLACE FUNCTION public.ojt_new_user_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
BEGIN INSERT INTO public.user_profiles(id,auth_user_id,email,name,role,active) VALUES(gen_random_uuid()::text,NEW.id::text,NEW.email,coalesce(NEW.raw_user_meta_data->>'name',split_part(NEW.email,'@',1)),'STUDENT',true); RETURN NEW; END $$;
CREATE TRIGGER ojt_auth_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.ojt_new_user_profile();
CREATE OR REPLACE FUNCTION public.ojt_role() RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT role::text FROM public.user_profiles WHERE auth_user_id=auth.uid()::text AND active $$;
CREATE OR REPLACE FUNCTION public.ojt_student_id() RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT s.id FROM public.students s JOIN public.user_profiles p ON p.id=s.user_id WHERE p.auth_user_id=auth.uid()::text $$;
CREATE OR REPLACE FUNCTION public.ojt_company_id() RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT company_id FROM public.supervisor_assignments a JOIN public.user_profiles p ON p.id=a.user_id WHERE p.auth_user_id=auth.uid()::text AND a.active $$;
ALTER TABLE "user_profiles" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "students" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "companies" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "supervisor_assignments" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "ojt_placements" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "biometric_enrollments" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "attendance_records" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "daily_documentations" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "document_versions" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "approval_records" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "digital_signatures" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "audit_logs" ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_read_self_or_coordinator ON "user_profiles" FOR SELECT USING(auth_user_id=auth.uid()::text OR public.ojt_role()='COORDINATOR');
CREATE POLICY students_read_scope ON "students" FOR SELECT USING(user_id IN (SELECT id FROM "user_profiles" WHERE auth_user_id=auth.uid()::text) OR public.ojt_role()='COORDINATOR' OR EXISTS(SELECT 1 FROM "ojt_placements" p WHERE p.student_id=id AND p.company_id=public.ojt_company_id()));
CREATE POLICY students_update_self ON "students" FOR UPDATE USING(user_id IN (SELECT id FROM "user_profiles" WHERE auth_user_id=auth.uid()::text)) WITH CHECK(user_id IN (SELECT id FROM "user_profiles" WHERE auth_user_id=auth.uid()::text));
CREATE POLICY companies_read_scope ON "companies" FOR SELECT USING(approved OR public.ojt_role()='COORDINATOR' OR id=public.ojt_company_id());
CREATE POLICY placements_read_scope ON "ojt_placements" FOR SELECT USING(student_id=public.ojt_student_id() OR public.ojt_role()='COORDINATOR' OR company_id=public.ojt_company_id());
CREATE POLICY placements_student_submit ON "ojt_placements" FOR INSERT WITH CHECK(student_id=public.ojt_student_id() AND status='PENDING');
CREATE POLICY biometric_read_self ON "biometric_enrollments" FOR SELECT USING(student_id=public.ojt_student_id() OR public.ojt_role()='COORDINATOR');
CREATE POLICY attendance_read_scope ON "attendance_records" FOR SELECT USING(student_id=public.ojt_student_id() OR public.ojt_role()='COORDINATOR' OR EXISTS(SELECT 1 FROM "ojt_placements" p WHERE p.student_id=attendance_records.student_id AND p.company_id=public.ojt_company_id()));
CREATE POLICY docs_read_scope ON "daily_documentations" FOR SELECT USING(student_id=public.ojt_student_id() OR public.ojt_role()='COORDINATOR' OR EXISTS(SELECT 1 FROM "ojt_placements" p WHERE p.student_id=daily_documentations.student_id AND p.company_id=public.ojt_company_id()));
CREATE POLICY docs_student_create ON "daily_documentations" FOR INSERT WITH CHECK(student_id=public.ojt_student_id());
CREATE POLICY versions_read_scope ON "document_versions" FOR SELECT USING(EXISTS(SELECT 1 FROM "daily_documentations" d WHERE d.id=documentation_id AND (d.student_id=public.ojt_student_id() OR public.ojt_role()='COORDINATOR' OR EXISTS(SELECT 1 FROM "ojt_placements" p WHERE p.student_id=d.student_id AND p.company_id=public.ojt_company_id()))));
CREATE POLICY approvals_read_scope ON "approval_records" FOR SELECT USING(public.ojt_role()='COORDINATOR' OR EXISTS(SELECT 1 FROM "document_versions" v JOIN "daily_documentations" d ON d.id=v.documentation_id WHERE v.id=version_id AND (d.student_id=public.ojt_student_id() OR EXISTS(SELECT 1 FROM "ojt_placements" p WHERE p.student_id=d.student_id AND p.company_id=public.ojt_company_id()))));
CREATE POLICY signatures_read_scope ON "digital_signatures" FOR SELECT USING(public.ojt_role()='COORDINATOR' OR EXISTS(SELECT 1 FROM "document_versions" v JOIN "daily_documentations" d ON d.id=v.documentation_id WHERE v.id=version_id AND (d.student_id=public.ojt_student_id() OR EXISTS(SELECT 1 FROM "ojt_placements" p WHERE p.student_id=d.student_id AND p.company_id=public.ojt_company_id()))));
CREATE POLICY audit_read_coordinator ON "audit_logs" FOR SELECT USING(public.ojt_role()='COORDINATOR');
-- No client-side write policies are granted for signature and audit tables. Route handlers use narrowly scoped server authority.
